templates.template:
.block-container--tagsFilter {
    margin-bottom: @xf-paddingMedium;

    .block-body {
        padding: @xf-paddingSmall;
    }

    .tagItem--menuItem {
        display: inline-block;
        padding: @xf-paddingSmall / 2 @xf-paddingSmall;
        border: 1px solid @xf-borderColorFeature;
        border-radius: @xf-borderRadiusMedium;
        background-color: @xf-contentBg;
        color: @xf-textColor;
        text-decoration: none;

        &:hover {
            background-color: @xf-borderColorFeature;
            color: @xf-textColorFeature;
        }
    }

    ul.listInline--separated > li:not(:last-child):after {
        content: ''; // Remove default separator if any, or customize
        margin: 0 @xf-paddingSmall / 2;
    }
}
